469	fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
470	    if global.dry_run {
471	        return Err(CliError::ReleasePlanDryRun);
472	    }
473	    let runner = CliCommandRunner;
474	    let source_global = source_global(global, args.source_root.as_deref());
475	    let workspace = load_workspace(&source_global, &runner)?;
476	    // Before any commit is read: a shallow or SHA-256 repository must report E266 or E265, not a lower-level git error.
477	    workspace
478	        .git_access()
479	        .require_trustable_repository()
480	        .map_err(callisto_graph::GraphError::from)?;
481	    let decision = match args.from_release_commit.as_deref() {
482	        Some(raw) => {
483	            let commit = callisto_model::CommitSha::parse(raw).map_err(|error| CliError::ReleaseCommitInvalid {
484	                raw: raw.to_owned(),
485	                detail: error.to_string(),
486	            })?;
487	            let decision_path = args
488	                .decision
489	                .as_deref()
490	                .expect("clap requires --decision alongside --from-release-commit");
491	            // The workflow intentionally passes an absolute decision path
492	            // from its separately checked-out release source. Git's commit
493	            // diff and `git show REV:path` both require a repository-relative
494	            // path, so normalize once at the CLI boundary rather than asking
495	            // graph code to infer a caller's checkout layout.
496	            let decision_path = if decision_path.is_absolute() {
497	                let decision_path = dunce::canonicalize(decision_path).map_err(|source| CliError::Io {
498	                    source,
499	                    path: Some(decision_path.to_path_buf()),
500	                })?;
501	                decision_path
502	                    .strip_prefix(&workspace.root)
503	                    .map_err(|_outside_source| CliError::ReleaseDecisionOutsideSource {
504	                        decision: decision_path.display().to_string(),
505	                        root: workspace.root.display().to_string(),
506	                    })?
507	                    .to_path_buf()
508	            } else {
509	                decision_path.to_path_buf()
510	            };
511	            let decision_path = callisto_model::workspace_relative(&decision_path).map_err(|error| {
512	                CliError::ReleaseDecisionPathInvalid {
513	                    path: decision_path.display().to_string(),
514	                    detail: error.to_string(),
515	                }
516	            })?;
517	            derive_release_commit_decision(&workspace, &commit, &decision_path)?
518	        }
519	        None => {
520	            let selections = parse_selections(&args.packages)?;
521	            let inference = select_inference();
522	            let version_plan =
523	                callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
524	            derive_selected_release_decision(&workspace, &version_plan, &selections)?
525	        }
526	    };
527	    let locator = IgnoreWalkLocator::new(&workspace.root);
528	    let (intent, diagnostics) = match (
529	        &workspace.config.product_release,
530	        &args.orchestration_revision,
531	        &args.artifact_repository,
532	    ) {
533	        (Some(_), Some(revision), Some(repository)) => {
534	            let workflow_commit = callisto_model::CommitSha::parse(revision).map_err(|error| {
535	                CliError::ReleaseOrchestrationRevisionInvalid {
536	                    revision: revision.clone(),
537	                    detail: error.to_string(),
538	                }
539	            })?;
540	            let repository = callisto_model::GitHubRepository::parse(repository).map_err(|error| {
541	                CliError::ReleaseArtifactRepositoryInvalid {
542	                    repository: repository.clone(),
543	                    detail: error.to_string(),
544	                }
545	            })?;
546	            // A missing forge-repository is the graph's error; only the match lives here.
547	            if let Some(configured) = workspace
548	                .config
549	                .product_release
550	                .as_ref()
551	                .and_then(|release| release.forge_repository.as_ref())
552	                .filter(|configured| **configured != repository)
553	            {
554	                return Err(CliError::ReleaseForgeRepositoryMismatch {
555	                    configured: configured.as_slug(),
556	                    requested: repository.as_slug(),
557	                });
558	            }
559	            build_release_intent_with_artifacts(
560	                &workspace.root,
561	                &locator,
562	                &runner,
563	                &decision,
564	                ExecutionTrustProfileV1::GitCommit,
565	                callisto_graph::commands::ArtifactBuildPolicy {
566	                    repository,
567	                    workflow_path: callisto_model::RELEASE_COORDINATOR_WORKFLOW_PATH.to_owned(),
568	                    workflow_commit,
569	                },
570	            )?
571	        }
572	        (Some(_), _, _) => {
573	            return Err(CliError::ReleaseOrchestrationFlagsRequired);
574	        }
575	        (None, revision, repository) => {
576	            // The release workflow always passes both flags, including for sources predating [release].
577	            if revision.is_some() || repository.is_some() {
578	                log_line(
579	                    global.format,
580	                    "notice: --orchestration-revision and --artifact-repository ignored: the source has no [release] section; planning with zero artifact slots",
581	                )?;
582	            }
583	            (
584	                build_release_intent(
585	                    &workspace.root,
586	                    &locator,
587	                    &runner,
588	                    &decision,
589	                    ExecutionTrustProfileV1::GitCommit,
590	                )?,
591	                Vec::new(),
592	            )
593	        }
594	    };
595	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
596	        .expect("release plan rejects --dry-run before creating its explicit output");
597	    write_intent(&args.out, &intent, &permit)?;
598	    for diagnostic in &diagnostics {
599	        eprintln!("warning: {}", diagnostic.message);
600	    }
601	    match global.format {
602	        OutputFormat::Json => emit_report(
603	            &mut std::io::stdout(),
604	            &ReleasePlanReport {
605	                intent: intent.clone(),
606	                diagnostics: diagnostics.clone(),
607	            },
608	            global.dry_run,
609	        )?,
610	        OutputFormat::Text => emit_line(&format!(
611	            "Wrote release intent {} to {}",
612	            intent.digest(),
613	            args.out.display()
614	        ))?,
615	    }
616	    Ok(ExitCode::SUCCESS)
617	}
