628	fn execute(args: ReleaseExecuteArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
629	    // Inputs and the receipt destination are checked before the first effect; a provider failure
630	    // mid-run still leaves landed effects without a receipt, and a rerun adopts them.
631	    let permit = ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleaseExecuteDryRun)?;
632	    let intent = read_intent(&args.intent)?;
633	    let orchestration_revision = callisto_model::CommitSha::parse(&args.orchestration_revision).map_err(|error| {
634	        CliError::ReleaseOrchestrationRevisionInvalid {
635	            revision: args.orchestration_revision.clone(),
636	            detail: error.to_string(),
637	        }
638	    })?;
639	    callisto_model::atomic::probe_atomic_write(&args.receipt, &permit).map_err(|source| CliError::Io {
640	        source,
641	        path: Some(args.receipt.clone()),
642	    })?;
643	    let manifest = args
644	        .artifact_manifest
645	        .as_deref()
646	        .map(read_artifact_manifest)
647	        .transpose()?;
648	    let sealed_python = manifest
649	        .as_ref()
650	        .is_some_and(|manifest| !manifest.distributions.is_empty());
651	    let needs_artifacts = sealed_python || !intent.artifact_slots.is_empty();
652	    let verified_artifacts = match (manifest.as_ref(), args.artifact_dir.as_deref()) {
653	        (None, None) if !needs_artifacts => None,
654	        (Some(manifest), Some(directory)) if needs_artifacts => {
655	            let runner = CliCommandRunner;
656	            Some(verify_artifact_manifest(&intent, manifest, directory, &runner)?)
657	        }
658	        _ if needs_artifacts => return Err(CliError::ReleaseMissingArtifactInputs),
659	        _ => return Err(CliError::ReleaseUnexpectedArtifactInputs),
660	    };
661	    // The run envelope is minted and cross-checked here, before the first
662	    // effect, and is then the single authority for every fact it carries.
663	    let envelope = ReleaseRunEnvelopeV1::new(
664	        orchestration_revision,
665	        &intent,
666	        verified_artifacts
667	            .as_ref()
668	            .map(|artifacts| artifacts.manifest().digest()),
669	    )
670	    .map_err(|error| CliError::ReleaseEnvelopeInvalid {
671	        detail: error.to_string(),
672	    })?;
673	    let runner = CliCommandRunner;
674	    let source_global = source_global(global, args.source_root.as_deref());
675	    let source_workspace = load_workspace(&source_global, &runner)?;
676	    // A missing forge-repository is the graph's error during intent validation; only the match lives here.
677	    if let Some(configured) = source_workspace
678	        .config
679	        .product_release
680	        .as_ref()
681	        .and_then(|release| release.forge_repository.as_ref())
682	        && let Some(slot) = intent
683	            .artifact_slots
684	            .iter()
685	            .find(|slot| slot.attestation_policy.repository != *configured)
686	    {
687	        return Err(CliError::ReleaseForgeRepositoryMismatch {
688	            configured: configured.as_slug(),
689	            requested: slot.attestation_policy.repository.as_slug(),
690	        });
691	    }
692	    // The workspace root, resolved exactly as `plan` resolves it. Executing
693	    // from a subdirectory must reach the same root, not the process cwd.
694	    let root = source_workspace.root.clone();
695	    let locator = IgnoreWalkLocator::new(&root);
696	    let capability = validate_release_intent(&root, &locator, &runner, intent)?;
697	    let state = execute_release(&capability, &permit, &envelope, verified_artifacts.as_ref())?;
698	    let receipt =
699	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
700	            detail: error.to_string(),
701	        })?;
702	    write_receipt(&args.receipt, &receipt, &permit)?;
703	    match global.format {
704	        OutputFormat::Json => emit_report(
705	            &mut std::io::stdout(),
706	            &ReleaseExecuteReport {
707	                receipt: receipt.clone(),
708	            },
709	            global.dry_run,
710	        )?,
711	        OutputFormat::Text => emit_line(&format!("Release receipt saved to {}", args.receipt.display()))?,
712	    }
713	    Ok(ExitCode::SUCCESS)
714	}
