724	fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
725	    let value = read_json_file(path)?;
726	    // A stale intent is the expected failure after a schema bump; name it
727	    // before serde reports it as an opaque parse error.
728	    let found = &value["schemaVersion"];
729	    if found != &serde_json::json!(ReleaseIntentV1::SCHEMA_VERSION) {
730	        return Err(CliError::ReleaseIntentSchemaUnsupported {
731	            path: path.to_path_buf(),
732	            found: found.to_string(),
733	            expected: ReleaseIntentV1::SCHEMA_VERSION,
734	        });
735	    }
736	    let wire: ReleaseIntentV1Wire = serde_json::from_value(value).map_err(|error| CliError::ReleaseIntentInvalid {
737	        path: path.display().to_string(),
738	        detail: error.to_string(),
739	    })?;
740	    Ok(ReleaseIntentV1::from_wire(wire)?)
741	}
742	
743	fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
744	    serde_json::from_value(read_json_file(path)?).map_err(|error| CliError::ArtifactManifestFileInvalid {
745	        path: path.display().to_string(),
746	        detail: error.to_string(),
747	    })
748	}
