750	fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
751	    let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
752	        source,
753	        path: Some(path.to_path_buf()),
754	    })?;
755	    serde_json::from_str(&content).map_err(|error| CliError::ReleaseJsonInvalid {
756	        path: path.display().to_string(),
757	        detail: error.to_string(),
758	    })
759	}
