761	fn write_intent(path: &std::path::Path, intent: &ReleaseIntentV1, permit: &ApplyPermit) -> Result<(), CliError> {
762	    let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
763	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
764	        source,
765	        path: Some(path.to_path_buf()),
766	    })?;
767	    Ok(())
768	}
