770	fn write_receipt(path: &std::path::Path, receipt: &ReleaseReceiptV1, permit: &ApplyPermit) -> Result<(), CliError> {
771	    let content = serde_json::to_string_pretty(receipt).expect("release receipt serializes") + "\n";
772	    callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
773	        source,
774	        path: Some(path.to_path_buf()),
775	    })
776	}
