50	#[serde(rename_all = "camelCase", deny_unknown_fields)]
51	struct ReleasePrDecisionInput {
52	    schema_version: u8,
53	    config: ReleasePrConfigWireV1,
54	    snapshot: ReleasePrSnapshotWireV2,
55	    action: ReleasePrActionV2,
56	    #[serde(default, deserialize_with = "deserialize_present")]
57	    command: Option<String>,
58	    #[serde(default, deserialize_with = "deserialize_present")]
59	    dry_run: Option<bool>,
60	}
