62	// Missing report metadata is allowed, but present null values are not.
63	fn deserialize_present<'de, D, T>(deserializer: D) -> Result<Option<T>, D::Error>
64	where
65	    D: serde::Deserializer<'de>,
66	    T: serde::Deserialize<'de>,
67	{
68	    T::deserialize(deserializer).map(Some)
69	}
