71	fn read_decision_arg(arg: &str) -> Result<ReleasePrDecisionWireV2, CliError> {
72	    let input: ReleasePrDecisionInput = read_json_arg_as("decision", arg)?;
73	    match (&input.command, input.dry_run) {
74	        (None, None) => {}
75	        (Some(command), Some(_)) if command == <ReleasePrDecideReport as callisto_model::Report>::COMMAND => {}
76	        _ => {
77	            return Err(CliError::ReleasePrArgJsonInvalid {
78	                flag: "decision",
79	                detail: "report metadata must include command=\"release-pr decide\" and a boolean dryRun".into(),
80	            });
81	        }
82	    }
83	    Ok(ReleasePrDecisionWireV2 {
84	        schema_version: input.schema_version,
85	        config: input.config,
86	        snapshot: input.snapshot,
87	        action: input.action,
88	    })
89	}
