91	fn verify(args: ReleasePrVerifyArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
92	    let decision_wire = read_decision_arg(&args.decision)?;
93	    let decision = ReleasePrDecisionV2::from_wire(decision_wire)?;
94	    let snapshot_wire: ReleasePrSnapshotWireV2 = read_json_arg_as("snapshot", &args.snapshot)?;
95	    let snapshot = ReleasePrSnapshotV2::from_wire(snapshot_wire)?;
96	    match args.applied_head {
97	        Some(head) => decision.verify_snapshot_after_update(&snapshot, &CommitSha::parse(&head)?)?,
98	        None => decision.verify_snapshot(&snapshot)?,
99	    }
100	    match global.format {
101	        OutputFormat::Json => emit_report(
102	            &mut std::io::stdout(),
103	            &ReleasePrVerifyReport { ok: true },
104	            global.dry_run,
105	        )?,
106	        OutputFormat::Text => emit_line("release PR decision still matches forge snapshot")?,
107	    }
108	    Ok(ExitCode::SUCCESS)
109	}
