138	/// A release PR merge must consume changesets, which pre mode keeps, so it fails before a PR is opened.
139	fn reject_pre_mode(workspace: &Workspace<'_, CliCommandRunner, ManifestWalkResolver>) -> Result<(), CliError> {
140	    let path = workspace.root.join(workspace.config.pre_json_path());
141	    let text = callisto_model::strict_fs::read_optional(&path).map_err(|error| GraphError::PreJsonRead {
142	        path: path.clone(),
143	        message: error.to_string(),
144	    })?;
145	    let Some(text) = text else { return Ok(()) };
146	    let state = parse_pre_json(&text).map_err(GraphError::PreJson)?;
147	    match state.mode {
148	        PreMode::Pre => Err(CliError::ReleasePrInPreMode { tag: state.tag }),
149	        PreMode::Exit => Ok(()),
150	    }
151	}
