153	fn commit_plan(args: ReleasePrCommitPlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
154	    let base_commit = CommitSha::parse(&args.base_commit)?;
155	
156	    let start = dunce::canonicalize(&global.cwd).map_err(|source| CliError::Io {
157	        source,
158	        path: Some(global.cwd.clone()),
159	    })?;
160	    let runner = CliCommandRunner;
161	    let git = GitAccess::new(&start, &runner);
162	    let changes = git.staged_changes_since(&base_commit)?;
163	    let plan = ReleasePrCommitPlanV1::from_changes(base_commit, args.message, changes)?;
164	
165	    match args.out {
166	        Some(path) => {
167	            let permit =
168	                ApplyPermit::granted_unless_dry_run(global.dry_run).ok_or(CliError::ReleasePrCommitPlanDryRun)?;
169	            let content = serde_json::to_string_pretty(&plan).expect("commit plan serializes") + "\n";
170	            callisto_model::atomic::atomic_write(&path, &content, &permit).map_err(|source| CliError::Io {
171	                source,
172	                path: Some(path),
173	            })?;
174	        }
175	        None => emit_report(
176	            &mut std::io::stdout(),
177	            &ReleasePrCommitPlanReport { plan },
178	            global.dry_run,
179	        )?,
180	    }
181	    Ok(ExitCode::SUCCESS)
182	}
