184	fn render_decision(decision: &ReleasePrDecisionV2) -> Result<(), CliError> {
185	    match &decision.action {
186	        ReleasePrActionV2::Noop { reason } => emit_line(&format!("release PR: no-op ({reason:?})"))?,
187	        ReleasePrActionV2::Create { branch, staging_branch } => {
188	            emit_line(&format!("release PR: create {branch} (staging {staging_branch})"))?
189	        }
190	        ReleasePrActionV2::Update {
191	            pull_request_number,
192	            branch,
193	            expected_head_commit,
194	            staging_branch,
195	        } => emit_line(&format!(
196	            "release PR: update #{pull_request_number} ({branch}, expected head {}, staging {staging_branch})",
197	            expected_head_commit.as_str()
198	        ))?,
199	        _ => emit_line("release PR: unsupported decision")?,
200	    }
201	    Ok(())
202	}
